            if (opts.parkedAt !== undefined && cmd.command.indexOf('/events?per_page=100') !== -1) {
                return '"' + opts.parkedAt + '"';
            }
            if (m && opts.committers && opts.committers[m[1]] !== undefined) {
                return '"' + opts.committers[m[1]] + '"';
