            notLabels: ['ai_validating'], notMergeState: ['BEHIND', 'DIRTY'], draft: false },
            localAction: 'validate_pr', skipIfValidatedHead: true, deferRedHead: true,
            limit: 1, id: 'validate-armed' }
    };

