                triggerSmIfIdle: function() {}
            },
            './configLoader.js': {
                loadProjectConfig: function() { return opts.config || {}; },
                resolveInstructions: function() { return { jobParamPatch: {} }; }
            },
            './common/outputFiles.js': outputFiles,
            './common/githubHelpers.js': githubHelpersStub,
