    // keeps the park).
    var machineLogin = String(machineAuthor || '').toLowerCase();
    var sha = headSha;
    for (var step = 0; sha && step < 10; step++) {
        var commit = headCommitActor(repoInfo, sha);
        if (!commit) return null;
        var login = String(commit.login || '').toLowerCase();
