                prStatus: { checkConclusion: 'red' }
            },
            onCliExecute: runsCli({ run: run('failure', 'ee55ff66aa', 40 * 60000, 20 * 60000) })
        }));
        sm.action({ jobParams: { owner: 'a', repo: 'b', machineAuthor: 'ai-teammate',
                                 rules: [RULES.armed] } });

