```js
/**
 * Machine-author resolution for the #687 PR lifecycle. ... (updated docs)
 * ... list docs ...
 */

function resolveMachineAuthor(jobParams, config) { ... unchanged ... }

/**
 * The raw config string as a LIST of logins (gh-728): the knob is a
 * comma-separated string — 'ai-teammate,github-actions[bot]' — and every
 * consumer treats it as a set of machine logins. Trimmed per entry;
 * empty entries dropped; null/absent → the empty list (every guard keyed
 * on it fails closed). Author-keyed guards match an entry with a
 * case-SENSITIVE exact compare (GitHub PR authors arrive canonicalized);
 * actor/committer probes (isMachineLogin) compare case-insensitively,
 * preserving the park probes' historical lowercase compare.
 */
function machineAuthorLogins(machineAuthor) {
    if (!machineAuthor) return [];
    var raw = String(machineAuthor).split(',');
    var out = [];
    for (var i = 0; i < raw.length; i++) {
        var entry = raw[i].trim();
        if (entry) out.push(entry);
    }
    return out;
}

/**
 * Case-insensitive list membership for ACTOR probes (parkResetCommit):
 * the sticky-park RESET has always lowercase-compared the head commit's
 * login against the machine login; with a list, ANY entry matching keeps
 * the park (a push by any machine login is machine movement).
 */
function isMachineLogin(login, machineAuthor) {
    var l = String(login || '').toLowerCase();
    if (!l) return false;
    var entries = machineAuthorLogins(machineAuthor);
    for (var i = 0; i < entries.length; i++) {
        if (entries[i].toLowerCase() === l) return true;
    }
    return false;
}
