    test('the first entry still matches (single-login behavior unchanged)', function () {
        assert.ok(isMachine({ author: 'ai-teammate' }, LIST, 'owner'));
        assert.ok(isMachine({ author: 'ai-teammate' }, 'ai-teammate', 'owner'));
