            // on the human 22:56 fix, newer than the 22:31 park
            actors: vfMergeActors({ mergeSha: BOT_MERGE_681, tipSha: HUMAN_FIX_681,
                                    tipLogin: 'istinn', tipDate: '2026-10-03T22:56:00Z' }),
