        assert.deepEqual(logins('ai-teammate,github-actions[bot]'),
            ['ai-teammate', 'github-actions[bot]']);
    });

    test('whitespace around entries is trimmed', function () {
        assert.deepEqual(logins('  ai-teammate ,  github-actions[bot]  '),
            ['ai-teammate', 'github-actions[bot]']);
    });

    test('empty segments are dropped', function () {
        assert.deepEqual(logins('ai-teammate,, ,github-actions[bot]'),
            ['ai-teammate', 'github-actions[bot]']);
    });

