                     '/commits/' + headSha +
                     '" --jq \'{login: (.author.login // .committer.login // ""), date: (.commit.committer.date // .committer.date // ""), committer: .commit.committer.name, sha: .sha, parents: [.parents[].sha]}\''
        });
