        assert.deepEqual(logins('ai-teammate,, ,github-actions[bot]'),
            ['ai-teammate', 'github-actions[bot]']);
    });

    test('non-string values are coerced (config.js may export numbers)', function () {
        assert.deepEqual(logins(12345), ['12345']);
